begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) select ('06000000-0000-4000-8000-00000000000'||i)::uuid,'data-test-'||i||'@example.test',now() from generate_series(1,5) i;
insert into public.children(id,name,dob,created_by) values('16000000-0000-4000-8000-000000000001','TEST',current_date-365,'06000000-0000-4000-8000-000000000001');
insert into public.child_members(child_id,user_id,role) select '16000000-0000-4000-8000-000000000001',('06000000-0000-4000-8000-00000000000'||i)::uuid,(array['owner','co_parent','family_contributor','family_viewer'])[i]::public.member_role from generate_series(1,4) i;
insert into public.consents(user_id,child_id,purpose,notice_version,verification_method,decision,granted_at)
 select m.user_id,m.child_id,p,'2026-10-24.v2','self_declaration','granted',now() from public.child_members m cross join unnest(enum_range(null::public.consent_purpose)) p where child_id='16000000-0000-4000-8000-000000000001';
create schema data_test;
grant usage on schema data_test to authenticated;
create function data_test.roles(i integer,label text,owner boolean) returns setof text language plpgsql as $$
declare cid uuid:='16000000-0000-4000-8000-000000000001'; stmt text; begin
 perform set_config('request.jwt.claim.sub',('06000000-0000-4000-8000-00000000000'||i)::text,true);
 stmt:=format('select public.request_data_export(%L)',cid);
 if owner then return next lives_ok(stmt,label||': can request export');
 else return next throws_ok(stmt,'PT403',null,label||': cannot export child');end if;
 return next throws_ok(format('select public.request_child_deletion(%L,%L)',cid,'WRONG'),case when owner then 'PT400' else 'PT403' end,null,label||': cannot delete without owner and confirmation');
 return next is((select count(*) from public.data_jobs where child_id=cid),case when owner then 1 else 0 end::bigint,label||': private export job visibility');
 return next is((select count(*) from public.deletion_receipts),0::bigint,label||': no other receipts');
 return next throws_ok('select public.claim_data_job()','42501',null,label||': workers not callable by client');
 return next is((select count(*) from storage.objects where bucket_id='family-exports'),0::bigint,label||': cannot read export bucket');
end $$;
grant execute on function data_test.roles(integer,text,boolean) to authenticated;
set local role authenticated;
select * from data_test.roles(1,'owner',true);
select * from data_test.roles(2,'co_parent',false);
select * from data_test.roles(3,'contributor',false);
select * from data_test.roles(4,'viewer',false);
select * from data_test.roles(5,'non_member',false);
reset role;
select is((select count(*) from public.audit_log where child_id='16000000-0000-4000-8000-000000000001' and entity='health_export' and action='create'),1::bigint,'Health export snapshot is audited');
select lives_ok($$select public.claim_data_job((select id from public.data_jobs where child_id='16000000-0000-4000-8000-000000000001' and kind='export'))$$,'Worker claims export');
select lives_ok($$select public.finish_data_job(id,lease,true,0,child_id::text||'/'||id::text||'/part-001.zip') from public.data_jobs where child_id='16000000-0000-4000-8000-000000000001' and kind='export'$$,'Empty-photo export still finishes with JSON');
set local role authenticated;
select set_config('request.jwt.claim.sub','06000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.authorize_export_part(id,0) from public.data_jobs where child_id='16000000-0000-4000-8000-000000000001'$$,'Owner can request audited export link');
select lives_ok($$select public.set_consent('16000000-0000-4000-8000-000000000001','health',false,'2026-10-24.v2')$$,'Withdraw health consent');
select throws_ok($$select public.authorize_export_part(id,0) from public.data_jobs where child_id='16000000-0000-4000-8000-000000000001'$$,'PT403',null,'Withdrawal blocks old health snapshot download');
select lives_ok($$select public.request_child_deletion('16000000-0000-4000-8000-000000000001','DELETE')$$,'Owner requests complete deletion');
select is((select count(*) from public.children where id='16000000-0000-4000-8000-000000000001'),0::bigint,'Deletion immediately hides child');
reset role;
select lives_ok($$select public.claim_data_job((select id from public.data_jobs where child_id='16000000-0000-4000-8000-000000000001' and kind='deletion'))$$,'Worker claims deletion');
select lives_ok($$select public.finish_data_job(id,lease,true,0) from public.data_jobs where child_id='16000000-0000-4000-8000-000000000001' and kind='deletion'$$,'Worker removes child after storage cleared');
select is((select count(*) from public.children where id='16000000-0000-4000-8000-000000000001'),0::bigint,'Child row is actually deleted');
select is((select count(*) from public.child_members where child_id='16000000-0000-4000-8000-000000000001'),0::bigint,'Membership cascades');
select is((select count(*) from public.consents where child_id='16000000-0000-4000-8000-000000000001'),0::bigint,'Consent data cascades');
select is((select count(*) from private.data_job_payloads where job_id in(select id from public.data_jobs where child_id='16000000-0000-4000-8000-000000000001')),0::bigint,'Health snapshots deleted');
select is((select count(*) from public.deletion_receipts where child_id='16000000-0000-4000-8000-000000000001'),1::bigint,'Minimal deletion receipt retained');
set local role authenticated;
select set_config('request.jwt.claim.sub','06000000-0000-4000-8000-000000000002',true);
select is((select count(*) from public.deletion_receipts),0::bigint,'Co-parent cannot read owner receipt');
select set_config('request.jwt.claim.sub','06000000-0000-4000-8000-000000000001',true);
select is((select count(*) from public.deletion_receipts),1::bigint,'Owner can read receipt after membership deletion');
reset role;
select ok((select bool_and(relrowsecurity) from pg_class where oid in('public.data_jobs'::regclass,'public.deletion_receipts'::regclass,'private.data_job_payloads'::regclass)),'Jobs, payloads and receipts have RLS');
select * from finish(); rollback;
